package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class MinimacRecipeTest {
    @TempDir Path directory;
    private Map<String,Object> group(Map<String,Object> parent,String name) {
        var result=new LinkedHashMap<String,Object>();((Map<?,?>)parent.get(name)).forEach((k,v)->result.put(k.toString(),v));parent.put(name,result);return result;
    }
    private Map<String,Object> base() throws IOException {
        Path resources=directory.resolve("resources");Files.createDirectories(resources);
        for(String name:List.of("reference.msav","reference-identities.tsv","target.vcf","target-identities.tsv"))if(!Files.exists(resources.resolve(name)))Files.writeString(resources.resolve(name),"metadata-test-placeholder:"+name);
        var m=new LinkedHashMap<String,Object>();m.put("schema_version",1L);m.put("operation","impute");m.put("profile",MinimacRecipe.CURRENT);m.put("assembly","explicit-test-build");m.put("resource_root","resources");
        m.put("reference",new LinkedHashMap<>(Map.of("path","reference.msav","identity_ledger","reference-identities.tsv","kind","msav","staging","copy-verbatim","column_semantics","person-samples")));
        m.put("target",new LinkedHashMap<>(Map.of("path","target.vcf","identity_ledger","target-identities.tsv","kind","phased-vcf","staging","gt-only-lf-bgzf","column_semantics","person-samples")));
        m.put("region",new LinkedHashMap<>(Map.of("contig","20","start",1L,"end",1000000L,"scope","autosomal","review","Explicit fixture region, not inferred from a contig alias")));
        var review=new LinkedHashMap<String,Object>();for(String key:List.of("organism","reference_panel","reference_sample_eligibility","target_sample_eligibility","assembly_region_ploidy","phase","allele_harmonization","variant_normalization"))review.put(key,"Reviewed fixture declaration: "+key);m.put("input_review",review);
        m.put("boundary_policy","VERIFY_SHARED_KEEP_LATER");m.put("phase_policy","require-pipe");m.put("target_missing_policy","exact-phased");m.put("target_only_markers","error");m.put("sample_overlap","error");m.put("id_policy","require-reference-id");m.put("observed_call_changes","retain-with-ledger");m.put("provided_phase_changes","retain-with-ledger");
        m.put("engine",new LinkedHashMap<>(Map.of("threads",1L,"parameter_policy","upstream-defaults","overrides",new LinkedHashMap<>())));
        m.put("post_imputation_qc",new LinkedHashMap<>(Map.of("kind","none")));
        m.put("limits",new LinkedHashMap<>(Map.of("samples",100L,"variants",10000L,"genotype_cells",1000000L,"input_bytes",1048576L,"decoded_characters",1048576L,"line_characters",8192L,"identity_rows",1000L,"retained_bytes",1048576L,"workspace_bytes",10485760L)));
        return m;
    }
    private Path recipe(Map<String,Object> m) throws IOException {Path p=Files.createTempFile(directory,"recipe-",".json");Files.writeString(p,RegenieRuntime.json(m));return p;}
    private MinimacRecipe.Spec parse(Map<String,Object> m) throws IOException {return MinimacRecipe.read(recipe(m));}
    private Map<String,Object> referenceOperation(String op) throws IOException {
        var m=base();m.put("operation",op);for(String key:List.of("target","target_missing_policy","target_only_markers","sample_overlap","observed_call_changes","provided_phase_changes","post_imputation_qc"))m.remove(key);
        if(op.equals("prepare-reference")){var ref=group(m,"reference");ref.put("kind","phased-vcf");ref.put("staging","gt-only-lf-bgzf");}
        if(op.equals("convert-reference")){var ref=group(m,"reference");ref.put("kind","m3vcf");ref.put("staging","lossless-gzip");ref.put("column_semantics","haplotype-columns");}
        return m;
    }
    @Test void completeImputationRecipeRetainsExactPoliciesAndSafeResolvedResources() throws Exception {var s=parse(base());assertTrue(s.modern());assertTrue(s.hasTarget());assertEquals("20",s.region().contig());assertEquals(directory.resolve("resources/reference.msav").toAbsolutePath(),s.reference().data());assertEquals("gt-only-lf-bgzf",s.target().staging());assertEquals("none",s.qc().kind());assertEquals(List.of(),s.engine().arguments());assertEquals(10485760,s.limits().workspaceBytes());}
    @Test void referenceOperationsRejectImplicitTargetProcessing() throws Exception {for(String op:List.of("prepare-reference","convert-reference","inspect-reference")){var m=referenceOperation(op);assertFalse(parse(m).hasTarget());m.put("target",base().get("target"));assertThrows(IOException.class,()->parse(m));}}
    @Test void allReferenceOperationInputKindsAndStagingAreExplicit() throws Exception {var m=referenceOperation("prepare-reference");group(m,"reference").put("kind","msav");assertThrows(IOException.class,()->parse(m));var conversion=referenceOperation("convert-reference");group(conversion,"reference").put("kind","mvcf");assertThrows(IOException.class,()->parse(conversion));var kinds=List.of("msav","mvcf","m3vcf","phased-vcf");for(String kind:kinds){var a=referenceOperation("inspect-reference");var ref=group(a,"reference");ref.put("kind",kind);ref.put("staging",kind.equals("phased-vcf")?"gt-only-lf-bgzf":kind.equals("m3vcf")?"preserve-compressed-source":"copy-verbatim");assertEquals(kind,parse(a).reference().kind());}}
    @Test void currentAndHistoricalReferenceFamiliesCannotBeSilentlySubstituted() throws Exception {var m=base();group(m,"reference").put("kind","m3vcf");group(m,"reference").put("staging","lossless-gzip");assertThrows(IOException.class,()->parse(m));for(String profile:List.of(MinimacRecipe.MIN3,MinimacRecipe.LEGACY100,MinimacRecipe.LEGACY102)){var a=base();a.put("profile",profile);assertThrows(IOException.class,()->parse(a));group(a,"reference").put("kind","m3vcf");group(a,"reference").put("staging","lossless-gzip");a.put("boundary_policy","REQUIRE_SHARED_KEEP_LATER");assertFalse(parse(a).modern());}}
    @Test void historicalReadersRequireSharedBoundaryAdmission() throws Exception {var m=base();m.put("profile",MinimacRecipe.MIN3);group(m,"reference").putAll(Map.of("kind","m3vcf","staging","lossless-gzip"));assertThrows(IOException.class,()->parse(m));}
    @Test void exactProfileAssemblyAndReviewCannotBeGuessed() throws Exception {for(String key:List.of("profile","assembly","phase_policy","boundary_policy","id_policy")){var m=base();m.remove(key);assertThrows(IOException.class,()->parse(m));}var m=base();m.put("profile","latest");assertThrows(IOException.class,()->parse(m));var n=base();group(n,"input_review").remove("phase");assertThrows(IOException.class,()->parse(n));}
    @Test void unknownFieldsAndInlineCommandsAreRejectedThroughoutTheRecipe() throws Exception {for(String container:List.of("reference","target","engine","limits","region","input_review","post_imputation_qc")){var m=base();group(m,container).put("command","untrusted-command");assertThrows(IOException.class,()->parse(m));}var m=base();m.put("executable","anything");assertThrows(IOException.class,()->parse(m));}
    @Test void resourceMembersCannotTraverseEscapeOrUsePlatformDependentDrivePaths() throws Exception {for(String name:List.of("../outside","a/../outside","./x","/outside","C:/outside","a\\b",".")){var m=base();group(m,"reference").put("path",name);assertThrows(IOException.class,()->parse(m));}}
    @Test void unicodeAndSpacesArePermittedUnderAnExplicitRealResourceRoot() throws Exception {var m=base();Path input=directory.resolve("resources/資料 test.msav");Files.writeString(input,"immutable");group(m,"reference").put("path","資料 test.msav");assertEquals(input.toAbsolutePath(),parse(m).reference().data());}
    @Test void nonexistentResourceRootFailsBeforeSnapshotPathsAreCreated() throws Exception {var m=base();m.put("resource_root","missing");assertThrows(IOException.class,()->parse(m));assertFalse(Files.exists(directory.resolve("missing")));}
    @Test void integerFieldsRejectRoundedFractionalOrExponentialLiterals() throws Exception {for(Object value:List.of(1.0,1.5,"1",true)){var m=base();m.put("schema_version",value);assertThrows(IOException.class,()->parse(m));}var m=base();Path p=recipe(m);String raw=Files.readString(p).replace("\"schema_version\":1","\"schema_version\":1.00000000000000000001");Files.writeString(p,raw);assertThrows(IOException.class,()->MinimacRecipe.read(p));}
    @Test void zeroNegativeOrIncoherentLimitsAndRegionEndpointsFail() throws Exception {for(String key:List.of("samples","variants","genotype_cells","input_bytes","decoded_characters","line_characters","identity_rows","retained_bytes","workspace_bytes")){var m=base();group(m,"limits").put(key,0L);assertThrows(IOException.class,()->parse(m));}var a=base();group(a,"region").put("start",100L);group(a,"region").put("end",99L);assertThrows(IOException.class,()->parse(a));}
    @Test void invalidContigAndControlTextCannotBecomeStagedArgumentsOrMetadata() throws Exception {for(String contig:List.of("20,foo","20>","20\\other","20 name")){var m=base();group(m,"region").put("contig",contig);assertThrows(IOException.class,()->parse(m));}var a=base();a.put("assembly","build\ninjection");assertThrows(IOException.class,()->parse(a));}
    @Test void currentEngineOverrideUnitsAndNumericTypesAreRecordedExactly() throws Exception {var m=base();group(m,"engine").putAll(Map.of("parameter_policy","overrides-with-pinned-defaults","overrides",new LinkedHashMap<>(Map.of("chunk_bases",20000000L,"overlap_bases",3000000L,"match_error",.01))));var s=parse(m);assertEquals(20000000L,s.engine().overrides().get("chunk_bases"));assertTrue(s.engine().overrides().get("chunk_bases") instanceof Long);assertTrue(s.engine().arguments().contains("--chunk"));assertTrue(s.engine().arguments().contains("20000000"));assertTrue(s.engine().arguments().contains("--match-error"));}
    @Test void currentProbabilityOverridesAreNeverSilentlyClamped() throws Exception {for(var entry:List.of(Map.entry("match_error",.6),Map.entry("minimum_target_ratio",1.1),Map.entry("minimum_recombination",-.01),Map.entry("template_probability",1.01))){var m=base();group(m,"engine").putAll(Map.of("parameter_policy","overrides-with-pinned-defaults","overrides",Map.of(entry.getKey(),entry.getValue())));assertThrows(IOException.class,()->parse(m));}}
    @Test void overridesCannotSetOutputsThreadsPhoneHomeOrUndeclaredReferenceMembership() throws Exception {for(String key:List.of("output","threads","phone_home","sample_ids","format","min_r2","command")){var m=base();group(m,"engine").putAll(Map.of("parameter_policy","overrides-with-pinned-defaults","overrides",Map.of(key,1L)));assertThrows(IOException.class,()->parse(m));}}
    @Test void explicitOverridePolicyCannotHideUnusedOrNonemptyDefaults() throws Exception {var m=base();group(m,"engine").put("overrides",Map.of("chunk_bases",100L));assertThrows(IOException.class,()->parse(m));var a=base();group(a,"engine").put("parameter_policy","overrides-with-pinned-defaults");assertThrows(IOException.class,()->parse(a));}
    @Test void legacyMbAndPercentUnitsStayDifferentFromCurrentBasesAndRatio() throws Exception {var m=base();m.put("profile",MinimacRecipe.LEGACY102);m.put("boundary_policy","REQUIRE_SHARED_KEEP_LATER");group(m,"reference").putAll(Map.of("kind","m3vcf","staging","lossless-gzip"));group(m,"engine").putAll(Map.of("parameter_policy","overrides-with-pinned-defaults","overrides",Map.of("chunk_length_mb",20.0,"minimum_target_ratio_percent",.01)));var s=parse(m);assertTrue(s.engine().arguments().contains("--ChunkLengthMb"));assertTrue(s.engine().arguments().contains("--minRatioPercent"));assertFalse(s.engine().arguments().contains("--min-ratio"));group(m,"engine").put("overrides",Map.of("chunk_bases",20000000L));assertThrows(IOException.class,()->parse(m));}
    @Test void minimac3ReferenceEstimationAndImputationRoundRulesDiffer() throws Exception {var m=referenceOperation("prepare-reference");m.put("profile",MinimacRecipe.MIN3);group(m,"engine").putAll(Map.of("parameter_policy","overrides-with-pinned-defaults","overrides",Map.of("rounds",0L)));assertThrows(IOException.class,()->parse(m));group(m,"engine").put("overrides",Map.of("rounds",5L,"states",200L,"low_memory",true));assertTrue(parse(m).engine().arguments().contains("--lowMemory"));var n=base();n.put("profile",MinimacRecipe.MIN3);n.put("boundary_policy","REQUIRE_SHARED_KEEP_LATER");group(n,"reference").putAll(Map.of("kind","m3vcf","staging","lossless-gzip"));group(n,"engine").putAll(Map.of("parameter_policy","overrides-with-pinned-defaults","overrides",Map.of("rounds",0L)));assertTrue(parse(n).engine().arguments().contains("0"));}
    @Test void sourceR2QcPreservesDecimalTextAndStrictOrInclusiveOperators() throws Exception {var m=base();group(m,"post_imputation_qc").putAll(Map.of("kind","source-INFO-R2","minimum","0.80000000000000000001","operator","gt","missing","exclude-with-ledger"));var s=parse(m);assertEquals("0.80000000000000000001",s.qc().threshold());assertEquals("gt",s.qc().operator());group(m,"post_imputation_qc").put("operator","ge");assertEquals("ge",parse(m).qc().operator());}
    @Test void renamedUpstreamIdsNeedAnUnambiguousExplicitPolicy() throws Exception {var m=base();m.put("id_policy","retain-upstream-id-with-ledger");assertEquals("retain-upstream-id-with-ledger",parse(m).idPolicy());m.put("id_policy","retain-original-with-ledger");assertThrows(IOException.class,()->parse(m));}
    @Test void ignoredCompressionOptionsCannotFallBackToDefaultsAsSuccessfulRequests() throws Exception {for(var item:List.of(Map.entry("minimum_block_markers",121L),Map.entry("maximum_block_markers",16L),Map.entry("slope_unit",1L))){var m=referenceOperation("prepare-reference");group(m,"engine").putAll(Map.of("parameter_policy","overrides-with-pinned-defaults","overrides",Map.of(item.getKey(),item.getValue())));String message=assertThrows(MinimacRecipe.UnavailableCapability.class,()->parse(m)).getMessage();assertTrue(message.contains("SKIP"));assertTrue(message.contains("120 variants"));assertTrue(message.contains("Required action"));}assertNotNull(parse(referenceOperation("prepare-reference")));}
    @Test void unsupportedHistoricalPreparationAndBinaryInspectionHaveNamedRecovery() throws Exception {for(String profile:List.of(MinimacRecipe.LEGACY100,MinimacRecipe.LEGACY102)){var m=referenceOperation("prepare-reference");m.put("profile",profile);assertThrows(MinimacRecipe.UnavailableCapability.class,()->parse(m));}var m=referenceOperation("inspect-reference");m.put("profile",MinimacRecipe.MIN3);assertTrue(assertThrows(MinimacRecipe.UnavailableCapability.class,()->parse(m)).getMessage().contains("complete traceable text export"));}
    @Test void sourceR2QcRejectsBinaryRoundedOrNonfiniteThresholdInput() throws Exception {for(Object value:List.of(.8,"NaN","Infinity","1.0001","-0.1")){var m=base();group(m,"post_imputation_qc").putAll(Map.of("kind","source-INFO-R2","minimum",value,"operator","gt","missing","error"));assertThrows(IOException.class,()->parse(m));}}
    @Test void noQcAndReferenceOperationsRejectUnusedThresholds() throws Exception {var m=base();group(m,"post_imputation_qc").put("minimum","0.3");assertThrows(IOException.class,()->parse(m));var a=referenceOperation("inspect-reference");a.put("post_imputation_qc",Map.of("kind","none"));assertThrows(IOException.class,()->parse(a));}
    @Test void checkRetainsAdmissionPoliciesButDoesNotClaimPostImputationQc() throws Exception {var m=base();m.put("operation","check");m.remove("post_imputation_qc");var s=parse(m);assertNull(s.qc());assertTrue(s.hasTarget());}
    @Test void nativeInspectionDoesNotRequireAnImputationInputEncoding() throws Exception {var m=referenceOperation("inspect-reference");group(m,"reference").putAll(Map.of("kind","mvcf","staging","copy-verbatim"));assertEquals("inspect-reference",parse(m).operation());}
    @Test void immutableSnapshotsBindRecipeAndAllOriginalAndStagedResources() throws Exception {Path p=recipe(base());var s=MinimacRecipe.read(p);Path owned=directory.resolve("owned");Files.createDirectory(owned);var snapshots=MinimacRecipe.snapshot(s,owned);assertEquals(5,snapshots.files().size());snapshots.verify();assertEquals(Files.readString(s.reference().data()),Files.readString(snapshots.files().get("reference-source")));Files.writeString(snapshots.files().get("target-source"),"changed");assertThrows(IOException.class,snapshots::verify);assertTrue(Files.readString(s.target().data()).startsWith("metadata-test-placeholder"));}
    @Test void changedRecipeOrOriginalInputCannotBeAdmittedAsTheOldSnapshot() throws Exception {Path p=recipe(base());var s=MinimacRecipe.read(p);Files.writeString(p,Files.readString(p)+"\n");Path owned=directory.resolve("owned");Files.createDirectory(owned);assertThrows(IOException.class,()->MinimacRecipe.snapshot(s,owned));assertFalse(Files.exists(owned.resolve("input-snapshots")));Path q=recipe(base());var t=MinimacRecipe.read(q);var snapshot=MinimacRecipe.snapshot(t,owned);Files.writeString(t.reference().data(),"changed-original");assertThrows(IOException.class,snapshot::verify);}
    @Test void snapshotDirectoryAndExistingMembersAreNeverOverwritten() throws Exception {var s=parse(base());Path owned=directory.resolve("owned");Files.createDirectory(owned);Files.createDirectory(owned.resolve("input-snapshots"));Files.writeString(owned.resolve("input-snapshots/recipe"),"sentinel");assertThrows(IOException.class,()->MinimacRecipe.snapshot(s,owned));assertEquals("sentinel",Files.readString(owned.resolve("input-snapshots/recipe")));}
    @Test void combinedInputByteCeilingAppliesBeforeAnySnapshotFileIsCreated() throws Exception {var m=base();group(m,"limits").put("input_bytes",32L);var s=parse(m);Path owned=directory.resolve("owned");Files.createDirectory(owned);assertThrows(IOException.class,()->MinimacRecipe.snapshot(s,owned));assertFalse(Files.exists(owned.resolve("input-snapshots")));}
    @Test void personSampleAndHaplotypeColumnSemanticsDoNotRegroupPeopleImplicitly() throws Exception {var limits=new MinimacVcf.Limits(100,100,1000,1048576,1048576,8192,1048576,1000);String h="contig\tcolumn_id\tcolumn_copy\tperson_id\tperson_copy\n";Path p=directory.resolve("ids.tsv");Files.writeString(p,h+"20\thapA\t1\tP\t1\n20\thapB\t1\tP\t2\n");var ids=MinimacVcf.identity(p,limits);MinimacRecipe.grouping(ids,"haplotype-columns");assertThrows(IOException.class,()->MinimacRecipe.grouping(ids,"person-samples"));Files.writeString(p,h+"20\tA\t1\tP\t1\n20\tA\t2\tP\t2\n");var diploid=MinimacVcf.identity(p,limits);MinimacRecipe.grouping(diploid,"person-samples");assertThrows(IOException.class,()->MinimacRecipe.grouping(diploid,"haplotype-columns"));}
    @Test void nestedRecipeAndEngineStateIsImmutableAfterAdmission() throws Exception {var s=parse(base());assertThrows(UnsupportedOperationException.class,()->s.source().put("profile","changed"));assertThrows(UnsupportedOperationException.class,()->((Map<?,?>)s.source().get("reference")).clear());assertThrows(UnsupportedOperationException.class,()->s.engine().overrides().clear());}
    @Test void malformedDuplicateOrNonUtf8JsonCannotMutateAnyInput() throws Exception {Path p=recipe(base());byte[] original=Files.readAllBytes(directory.resolve("resources/reference.msav"));String raw=Files.readString(p);Files.writeString(p,raw.replace("\"schema_version\":1","\"schema_version\":1,\"schema_version\":1"));assertThrows(IOException.class,()->MinimacRecipe.read(p));Files.write(p,new byte[]{(byte)255});assertThrows(IOException.class,()->MinimacRecipe.read(p));assertArrayEquals(original,Files.readAllBytes(directory.resolve("resources/reference.msav")));}
}

